def load_details() -> list[dict]:
    fields = ("number", "actors", "preconditions", "inputs", "rules", "exceptions", "evidence", "dependencies", "boundary_case")
    rows = []
    for line in DETAIL_LINES.strip().splitlines():
        parts = line.split("|")
        if len(parts) != len(fields):
            raise ValueError(f"细化字段数量不正确：{parts[0]}")
        row = dict(zip(fields, parts))
        row["id"] = "P11-F" + row.pop("number")
        number=int(row['id'][-2:])
        row['current_phase_scope']='DEFERRED' if number==51 else 'PARTIAL' if number in (23,52,58,65,68,78) else 'CURRENT'
        row['scope_note']='本轮以React/Taro小程序、React/Vite Web、协议转发及赛事收单为重点；部署/HTTPS/运维与可观测性延后。'
        if number==51:
            row['rules']='监控指标工程本轮延后；订单/接受/计量与账证由对应交易功能保留，不建设仪表盘或告警'
            row['evidence']='DEFERRED，不计通过；后续恢复范围后再确定指标与验收'
            row['preconditions']='用户后续明确恢复可观测性范围后另行规划'
        if number==23:
            row['actors']='运营、安全、交易负责人'
            row['preconditions']='分角色开关与受权业务状态已实现；可观测性延后'
            row['inputs']='能力开关、限速、人工审核依据、业务意图ID'
            row['rules']='按seller/设备/SKU/模式停新售，保留既有结果和售后；交易异常人工处理，技术监控/自动告警延后'
        if number==52:
            row['rules']='按当前对象/端侧保留与删除规则执行，运行中删除及离线补清有效；备份恢复方案本轮延后'
            row['boundary_case']='节点离线后删除请求仍保留，重新联网执行补清且不误删私人资料；备份恢复场景延后'
        if number in (50,55):
            row['evidence']=row['evidence'].replace('异常导出告警','受权导出记录').replace('到期告警','到期撤证记录')
        rows.append(row)
    if [row["id"] for row in rows] != [f"P11-F{i:02d}" for i in range(1, 81)]:
        raise ValueError("必须完整且依序覆盖80项需求")
    return rows


